const t=a=>Math.max(0,Math.min(1,Number(a)||0));function o(a,h,n){if(!n)return{x:0,y:0,width:a,height:h};const x=Math.floor(t(n.x)*a),M=Math.floor(t(n.y)*h),i=Math.min(a,Math.max(x+1,Math.ceil(t(n.x+n.width)*a))),m=Math.min(h,Math.max(M+1,Math.ceil(t(n.y+n.height)*h)));return{x,y:M,width:i-x,height:m-M}}function y(a,h){const n=Math.min(t(a.x),t(h.x)),x=Math.min(t(a.y),t(h.y));return{x:n,y:x,width:Math.abs(t(h.x)-t(a.x)),height:Math.abs(t(h.y)-t(a.y))}}export{y as a,o as c};
